#!/usr/bin/env bash
# Decide metadata DB: external MySQL/PG/Oracle if configured, else embedded SQLite.
# shellcheck disable=SC1091
# Expects HUE_CONF_DIR / HUE_DATA_DIR already set (via env.sh).

packaging_conf_engine_lines() {
  # Uncommented engine= from user/packaging conf — ignore auto-generated sqlite override
  local f
  for f in "${HUE_CONF_DIR}"/*.ini; do
    [[ -f "${f}" ]] || continue
    [[ "$(basename "${f}")" == "z-95-sqlite.ini" ]] && continue
    grep -E '^[[:space:]]*engine[[:space:]]*=' "${f}" 2>/dev/null \
      | sed 's/[[:space:]]*#.*//' \
      | sed 's/^[[:space:]]*engine[[:space:]]*=[[:space:]]*//' \
      | sed 's/[[:space:]]*$//' \
      | grep -v '^$' || true
  done
}

packaging_using_external_db() {
  local engines engine
  engines="$(packaging_conf_engine_lines)"
  [[ -z "${engines}" ]] && return 1
  # Prefer external if ANY non-sqlite engine is configured (excluding z-95-sqlite.ini)
  while IFS= read -r engine; do
    [[ -z "${engine}" ]] && continue
    engine="$(printf '%s' "${engine}" | tr '[:upper:]' '[:lower:]')"
    case "${engine}" in
      *sqlite*) continue ;;
      *mysql*|*mariadb*|*postgresql*|*postgres*|*oracle*)
        return 0
        ;;
      *)
        return 0
        ;;
    esac
  done <<< "${engines}"
  return 1
}

packaging_ensure_sqlite() {
  local sqlite_ini="${HUE_CONF_DIR}/z-95-sqlite.ini"
  local db_file="${HUE_DATA_DIR}/desktop.db"

  # Remove stale runtime sqlite override when external DB is configured
  if packaging_using_external_db; then
    rm -f "${sqlite_ini}"
    echo "DB: using external database from ${HUE_CONF_DIR}"
    return 0
  fi

  mkdir -p "${HUE_DATA_DIR}"
  cat > "${sqlite_ini}" <<EOF
# Auto-generated by bin/start.sh — embedded SQLite (no external DB configured)
# To use MySQL instead: copy etc/z-90-database.mysql.ini.example to
# conf/z-90-database.ini and fill in host/user/password/name, then restart.
[desktop]
[[database]]
engine=sqlite3
name=${db_file}
EOF
  echo "DB: using embedded SQLite at ${db_file}"
}
